    #[inductive(initialize)]
    fn initialize_inductive(post: Self) { }

    #[inductive(delete_key_value)]
    fn delete_key_value_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |r, c|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && post.matrix[r][c].is_some() && post.matrix[r][c].unwrap().0 == key2 by {
            if post.frag[key2].is_some() {
                assert(key2 != key);
                let e = choose |e: (nat, nat)| 0 <= e.0 < HEIGHT && 0 <= e.1 < WIDTH
                    && pre.matrix[e.0][e.1 as int].is_some()
                    && pre.matrix[e.0][e.1 as int].unwrap().0 == key2;
                assert(post.matrix[e.0][e.1 as int] == pre.matrix[e.0][e.1 as int]);
                assert(post.matrix[e.0][e.1 as int].is_some());
                assert(post.matrix[e.0][e.1 as int].unwrap().0 == key2);
            }
        };
    }

    #[inductive(update_key_value)]
    fn update_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |r, c|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && post.matrix[r][c].is_some() && post.matrix[r][c].unwrap().0 == key2 by {
            if post.frag[key2].is_some() {
                if key2 == key {
                    assert(post.matrix[row][col as int].is_some());
                    assert(post.matrix[row][col as int].unwrap().0 == key2);
                } else {
                    let e = choose |e: (nat, nat)| 0 <= e.0 < HEIGHT && 0 <= e.1 < WIDTH
                        && pre.matrix[e.0][e.1 as int].is_some()
                        && pre.matrix[e.0][e.1 as int].unwrap().0 == key2;
                    assert(post.matrix[e.0][e.1 as int] == pre.matrix[e.0][e.1 as int]);
                }
            }
        };
        assert forall |key2: Key| post.frag[key2].is_some() ==> pre.frag[key2].is_some() by {
            if post.frag[key2].is_some() {
                assert(post.frag[key2] == pre.frag.insert(key, Some(new_val))[key2]);
                if key2 == key { assert(pre.frag[key2].is_some()); }
            }
        };
    }

    #[inductive(insert_key_value)]
    fn insert_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |r, c|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && post.matrix[r][c].is_some() && post.matrix[r][c].unwrap().0 == key2 by {
            if post.frag[key2].is_some() {
                if key2 == key {
                    assert(post.matrix[row][col as int].is_some());
                    assert(post.matrix[row][col as int].unwrap().0 == key2);
                } else {
                    let e = choose |e: (nat, nat)| 0 <= e.0 < HEIGHT && 0 <= e.1 < WIDTH
                        && pre.matrix[e.0][e.1 as int].is_some()
                        && pre.matrix[e.0][e.1 as int].unwrap().0 == key2;
                    assert(post.matrix[e.0][e.1 as int] == pre.matrix[e.0][e.1 as int]);
                }
            }
        };
        assert forall |key2: Key| post.frag[key2].is_some() ==> pre.frag[key2].is_some() by {
            if post.frag[key2].is_some() {
                if key2 != key {
                    assert(post.frag[key2] == pre.frag[key2]);
                    assert(pre.frag[key2].is_some());
                }
            }
        };
    }

    #[inductive(swing)]
    fn swing_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col, row2: Row, col2: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |r, c|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && post.matrix[r][c].is_some() && post.matrix[r][c].unwrap().0 == key2 by {
            if post.frag[key2].is_some() {
                let e = choose |e: (nat, nat)| 0 <= e.0 < HEIGHT && 0 <= e.1 < WIDTH
                    && pre.matrix[e.0][e.1 as int].is_some()
                    && pre.matrix[e.0][e.1 as int].unwrap().0 == key2;
                assert(post.matrix[e.0][e.1 as int] == pre.matrix[e.0][e.1 as int]);
            }
        };
        assert forall |key2: Key| post.frag[key2].is_some() ==> pre.frag[key2].is_some() by {
            if post.frag[key2].is_some() {
                assert(post.frag[key2] == pre.frag[key2]);
                assert(pre.frag[key2].is_some());
            }
        };
    }
