         assert forall |key2: Key| post.frag[key2].is_some() ==> pre.frag[key2].is_some() by {
             if post.frag[key2].is_some() {
                 assert(post.frag[key2] == pre.frag[key2]);
                 assert(pre.frag[key2].is_some());
             }
         };
     }
