                    let tracked (Tracked(mpt0), Tracked(tok0)) =
                        self.instance.update_key_value(key, new_val, h2x as nat, i as nat, mpt, r.token);
                    mpt = mpt0;
                    r.token = tok0;
                }
                Tracked(Commit(mpt))
            });

