    #[inductive(initialize)]
    fn initialize_inductive(post: Self) { }

    #[inductive(delete_key_value)]
    fn delete_key_value_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |row2, col2|
            0 <= row2 < HEIGHT && 0 <= col2 < WIDTH
                && post.matrix[row2][col2].is_some()
                && post.matrix[row2][col2].unwrap().0 == key2) by {
            if post.frag[key2].is_some() {
                assert(key2 != key);
                let row2 = choose |r| exists |c| 0 <= r < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == key2;
                let col2 = choose |c| 0 <= row2 < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[row2][c].is_some() && pre.matrix[row2][c].unwrap().0 == key2;
                assert(post.matrix[row2][col2] == pre.matrix[row2][col2]);
            }
        };
    }

    #[inductive(update_key_value)]
    fn update_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |row2, col2|
            0 <= row2 < HEIGHT && 0 <= col2 < WIDTH
                && post.matrix[row2][col2].is_some()
                && post.matrix[row2][col2].unwrap().0 == key2) by {
            if post.frag[key2].is_some() {
                let row2 = choose |r| exists |c| 0 <= r < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == key2;
                let col2 = choose |c| 0 <= row2 < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[row2][c].is_some() && pre.matrix[row2][c].unwrap().0 == key2;
                assert(post.matrix[row2][col2] == pre.matrix[row2][col2]);
            }
        };
    }

    #[inductive(insert_key_value)]
    fn insert_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |row2, col2|
            0 <= row2 < HEIGHT && 0 <= col2 < WIDTH
                && post.matrix[row2][col2].is_some()
                && post.matrix[row2][col2].unwrap().0 == key2) by {
            if post.frag[key2].is_some() {
                if key2 == key {
                    assert(post.matrix[row][col].is_some());
                    assert(post.matrix[row][col].unwrap().0 == key2);
                } else {
                    let row2 = choose |r| exists |c| 0 <= r < HEIGHT && 0 <= c < WIDTH
                        && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == key2;
                    let col2 = choose |c| 0 <= row2 < HEIGHT && 0 <= c < WIDTH
                        && pre.matrix[row2][c].is_some() && pre.matrix[row2][c].unwrap().0 == key2;
                    assert(post.matrix[row2][col2] == pre.matrix[row2][col2]);
                }
            }
        };
    }

    #[inductive(swing)]
    fn swing_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col, row2: Row, col2: Col) {
        broadcast use group_imap_lemmas;
        assert forall |key2: Key| post.frag[key2].is_some() ==> exists |row2, col2|
            0 <= row2 < HEIGHT && 0 <= col2 < WIDTH
